  "bots.setup.guide.telegram.create.1": "افتح @BotFather في تيليجرام وأنشئ بوتًا جديدًا.",
  "bots.setup.guide.telegram.create.2": "انسخ الرمز المميز لواجهة HTTP API الذي يرجعه BotFather والصقه في هذا النموذج.",
  "bots.setup.guide.telegram.create.3": "من المفيد فتح محادثة البوت الخاصة الآن لأن أمر الربط يجب إرساله هناك.",
  "bots.setup.guide.telegram.bind.1": "عُد إلى تيليجرام وافتح المحادثة الخاصة مع البوت الذي أنشأته.",
  "bots.setup.guide.telegram.bind.2": "إذا لم تبدأ المحادثة من قبل، فاضغط Start أو أرسل أي رسالة أولًا، ثم أرسل {command}.",
  "bots.setup.guide.telegram.bind.3": "عُد إلى هنا بعد أن يؤكد تيليجرام نجاح الربط.",
  "bots.setup.guide.weixin.create.1": "ابدأ تسجيل الدخول برمز QR في Weixin، وامسح الرمز ضوئيًا باستخدام Weixin، ثم أكّد على هاتفك.",
  "bots.setup.guide.weixin.create.2": "يحفظ DeepCode Studio القيمة bot_token التي يرجعها iLink تلقائيًا؛ وبعد المسح، أرسل أي رسالة إلى البوت في Weixin لتفعيل المحادثة.",
  "bots.setup.guide.weixin.create.3": "يستخدم DeepCode Studio عميل iLink مدمجًا: ‏`/ilink/bot/getupdates` للاستقصاء الطويل و`/ilink/bot/sendmessage` للردود.",
  "bots.setup.guide.weixin.bind.1": "افتح المحادثة المباشرة في Weixin التي تريد ربطها.",
  "bots.setup.guide.weixin.bind.2": "أرسل {command}.",
  "bots.setup.guide.weixin.bind.3": "عُد إلى هنا بعد نجاح الربط لإتمام إعدادات مساحة العمل و CLI الافتراضية.",
  "bots.setup.guide.feishu.create.1": "أنشئ تطبيقًا خاصًا في وحدة تحكم مطوري Feishu/Lark وفعّل إمكانية البوت.",
  "bots.setup.guide.feishu.create.2": "انسخ App ID و App Secret، ثم فعّل أحداث الاتصال الدائم لـ `im.message.receive_v1` وإجراءات البطاقات.",
  "bots.setup.guide.feishu.create.3": "اختر نطاق Feishu أو Lark المطابق هنا، ثم الصق بيانات الاعتماد في النموذج.",
  "bots.setup.guide.feishu.bind.1": "ثبّت التطبيق في مؤسستك وافتح محادثة مباشرة مع البوت.",
  "bots.setup.guide.feishu.bind.2": "أرسل {command} في تلك المحادثة المباشرة.",
  "bots.setup.guide.feishu.bind.3": "عُد إلى هنا بعد نجاح الربط لإتمام إعدادات مساحة العمل و CLI الافتراضية.",
  "bots.setup.guide.webhook.create.1": "لا يتطلب وضع Webhook بوتًا أصليًا في المنتج الخارجي؛ يكفي أن ترسل عملية الربط لديك الرسائل إلى DeepCode Studio بطريقة POST.",
  "bots.setup.guide.webhook.create.2": "اضبط سرًا مشتركًا أولًا؛ وأضف أيضًا عنوان URL صادرًا لـ Webhook إذا أردت استلام الردود غير المتزامنة.",
  "bots.setup.guide.webhook.create.3": "احتفظ بمعرّف userId ثابت لكل مستخدم خارجي حتى يرتبط الربط والسياق اللاحق بالشخص نفسه.",
  "bots.setup.guide.webhook.bind.1": "أرسل استدعاء رسالة خاصة بطريقة POST إلى نقطة النهاية `/api/bots/webhook` في DeepCode Studio.",
  "bots.setup.guide.webhook.bind.2": 'يجب أن تتضمن الحمولة على الأقل هذا المعرّف botId ومعرّف userId ثابتًا و`chatType: "private"`، مع ضبط النص على {command}.',
  "bots.setup.guide.webhook.bind.3": "إذا كان البوت يستخدم سرًا، فأرسل أيضًا الترويسة `x-zcode-bot-secret`؛ ثم عُد إلى هنا بعد نجاح الربط.",
