  "settings.modelProvider.help.contextWindow": "سعة السياق التي يعالجها النموذج دفعة واحدة، بالرموز. يستخدمها DeepCode Studio لإدارة السياق.\nلا تتجاوز الحد الفعلي للنموذج.",
  "settings.modelProvider.help.maxOutputTokens": "الحد الأقصى لعدد الرموز التي يمكن لطلب نموذج واحد توليده.\nلا تتجاوز الحد الفعلي للنموذج.",
  "settings.modelProvider.help.inputModalities": "اضبط أنواع المحتوى التي يستقبلها النموذج:\n\n- **نص**: يستقبل محتوى نصيًا. مطلوب.\n- **صور**: يستقبل محتوى صور.\n- **فيديو**: يستقبل محتوى فيديو.\n- **PDF**: يستقبل مستندات PDF مباشرة.",
  "settings.modelProvider.help.outputModalities": "نوع محتوى ردود النموذج. لا يُدعم حاليًا سوى النص.",
  "settings.modelProvider.help.capabilities": "- **المخرجات المهيكلة**: يدعم قيود JSON Schema على حقول المخرجات وأنواعها وبنيتها.\n- **البحث الأصلي في الويب**: يدعم قدرة البحث في الويب المدمجة في API النموذج.\n- **رسائل النظام أثناء المحادثة**: يدعم إدراج تعليمات النظام أثناء المحادثة.\n\nلا تفعّل قدرات لا يدعمها النموذج.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "اضبط مستويات التفكير المتاحة في الدردشة. **يجب ترتيبها من أقل جهد تفكير إلى أعلاه**.\nلا تضبط مستويات تفكير لا يدعمها النموذج.",
  "settings.modelProvider.help.reasoningLevelMapping": "استخدم تعبير CEL لربط مستوى التفكير الحالي، `reasoningLevel`، بحقول طلب API النموذج. يُدمج كائن JSON الذي يرجعه التعبير في جسم الطلب الصادر.",
  "settings.modelProvider.help.advanced": "**مخطط أدوات MFJS**: يفعّل توافق Moonshot Flavored JSON Schema، الشائع في API نموذج Kimi من Moonshot. فعّله فقط عندما يتطلب API النموذج هذا التنسيق.",
  "settings.modelProvider.help.followRecommendedConfig": "يطابق الإعدادات الموصى بها باستخدام معرّف النموذج وعنوان URL الأساسي وصيغة API. يحدّث DeepCode Studio التوصيات باستمرار ويزامنها إليك تلقائيًا.\nعند تغيير إعداد يدويًا، يصبح هذا الإعداد مُدارًا يدويًا ويتوقف عن اتباع تحديثات التوصيات؛ وتبقى الإعدادات الأخرى مُدارة بواسطة الإعدادات الذكية.",
